import './StatusList.css';
import type { Status, StatusItem } from '../../types';

export const STATUS_LABELS: Record<Status, string> = {
  todo: 'To Do',
  'in-progress': 'In Progress',
  review: 'In Review',
  done: 'Done',
  blocked: 'Blocked',
};

export const SKELETON_COUNT = 6;

export function statusColor(status: Status): string {
  const map: Record<Status, string> = {
    todo: 'status-color-todo',
    'in-progress': 'status-color-in-progress',
    review: 'status-color-review',
    done: 'status-color-done',
    blocked: 'status-color-blocked',
  };
  return map[status];
}

function skeletonWidthClass(index: number): string {
  const cycle = index % 3;
  if (cycle === 0) {
    return 'skeleton-line-long';
  }
  if (cycle === 1) {
    return 'skeleton-line-medium';
  }
  return 'skeleton-line-short';
}

function groupByStatus(items: StatusItem[]): Map<Status, StatusItem[]> {
  const order: Status[] = ['todo', 'in-progress', 'review', 'done', 'blocked'];
  const groups = new Map<Status, StatusItem[]>();
  for (const status of order) {
    const group = items.filter((item) => item.status === status);
    if (group.length > 0) {
      groups.set(status, group);
    }
  }
  return groups;
}

interface StatusListProps {
  // null = loading; array (possibly empty) = loaded
  items: StatusItem[] | null;
}

export function StatusList({ items }: StatusListProps): JSX.Element {
  if (items === null) {
    return (
      <ul className="status-list" aria-label="Status list">
        {Array.from({ length: SKELETON_COUNT }, (_, i) => (
          <li key={i} className="status-item-skeleton">
            <span className={`skeleton-line ${skeletonWidthClass(i)}`} />
          </li>
        ))}
      </ul>
    );
  }

  const groups = groupByStatus(items);

  return (
    <ul className="status-list" aria-label="Status list">
      {Array.from(groups.entries()).map(([status, groupItems]) => (
        <li key={status} className="status-group">
          <ul className="status-group-items">
            <li className="status-group-heading">
              <span className={statusColor(status)}>{STATUS_LABELS[status]}</span>
            </li>
            {groupItems.map((item) => (
              <li key={item.id} className="status-item">
                {item.label}
              </li>
            ))}
          </ul>
        </li>
      ))}
    </ul>
  );
}
